# La regla de alerta que vigila el plazo (LV-447). Idempotente **por nombre**, como
# `seed_alert_rules`: nueva, no renombra ninguna existente. Sólo se agrega a las
# empresas que ya usan reglas (las que no las sembraron no reciben avisos de nada).
RULE = ("Revisión REG-016 en 24 h", "compliance.missionreview", "due_on", 0)


def add_review_rule(apps, schema_editor):
    AlertRule = apps.get_model("compliance", "AlertRule")
    name, entity_type, field_to_watch, days = RULE
    tenants = AlertRule.objects.values_list("tenant_id", flat=True).distinct()
    for tenant_id in list(tenants):
        AlertRule.objects.get_or_create(
            tenant_id=tenant_id,
            name=name,
            defaults={
                "entity_type": entity_type,
                "field_to_watch": field_to_watch,
                "days_before_expiry": days,
                "enabled": True,
                "create_kanban_task": False,
            },
        )


def remove_review_rule(apps, schema_editor):
    AlertRule = apps.get_model("compliance", "AlertRule")
    Alert = apps.get_model("compliance", "Alert")
    rules = AlertRule.objects.filter(name=RULE[0], entity_type=RULE[1])
    # Sólo se borra la que nadie usó: una con alertas es evidencia.
    for rule in rules:
        if not Alert.objects.filter(alert_rule=rule).exists():
            rule.delete()


